import React, { useState } from 'react';
import AceEditor from 'react-ace';
import axios from 'axios';
import { toast } from 'react-toastify';

import 'ace-builds/src-noconflict/mode-c_cpp';
import 'ace-builds/src-noconflict/mode-java';
import 'ace-builds/src-noconflict/mode-python';
import 'ace-builds/src-noconflict/mode-javascript';
import 'ace-builds/src-noconflict/theme-monokai';

const Compiler = () => {
  const [code, setCode] = useState('');
  const [language, setLanguage] = useState('python');
  const [output, setOutput] = useState('');
  const [loading, setLoading] = useState(false);

  const languageIds = {
    c: 50,
    cpp: 54,
    java: 62,
    python: 71,
    javascript: 63,
  };

  const handleRun = async () => {
    setLoading(true);
    try {
      const res = await axios.post('http://localhost:5000/api/compile', {
        language_id: languageIds[language],
        source_code: code,
      });
      setOutput(res.data.stdout || res.data.stderr || 'No output');
    } catch (err) {
      setOutput('Error compiling code');
    }
    setLoading(false);
  };

  return (
    <div className="container mx-auto p-8">
      <h1 className="text-2xl font-bold mb-4">Online Code Compiler</h1>
      <select value={language} onChange={(e) => setLanguage(e.target.value)} className="mb-4 p-2 border">
        <option value="c">C</option>
        <option value="cpp">C++</option>
        <option value="java">Java</option>
        <option value="python">Python</option>
        <option value="javascript">JavaScript</option>
      </select>
      <AceEditor
        mode={language === 'cpp' ? 'c_cpp' : language}
        theme="monokai"
        value={code}
        onChange={setCode}
        name="code-editor"
        editorProps={{ $blockScrolling: true }}
        setOptions={{
          enableBasicAutocompletion: true,
          enableLiveAutocompletion: true,
          enableSnippets: true,
        }}
        width="100%"
        height="400px"
      />
      <button onClick={handleRun} disabled={loading} className="mt-4 bg-blue-600 text-white p-2">
        {loading ? 'Running...' : 'Run Code'}
      </button>
      <div className="mt-4 p-4 bg-gray-100">
        <h2 className="font-bold">Output:</h2>
        <pre>{output}</pre>
      </div>
    </div>
  );
};

export default Compiler;
